          deployStatus === "success"
            ? "healthy"
            : deployStatus === "failed"
            ? "critical"
            : "degraded",
        lastCheck: new Date().toISOString(),
        metrics: {
          latency: 0,
          errorRate: deployStatus === "success" ? 0 : 1,
          requestsPerMinute: 0,
        },
      },
    ];

    // Stub alerts
    const Alerts = [
      {
        level: "warning" as const,
        message: "Media Generator showing increased latency",
