      let log = [];
      if (fs.existsSync(TRADING_LOG)) {
        log = JSON.parse(fs.readFileSync(TRADING_LOG, "utf-8"));
      }
      // Confidence and real funds status from last trade
      const last = log.length > 0 ? log[log.length - 1] : null;
      // Analytics: profit, win rate, trade count, pairs, etc.
      const totalProfit = log.reduce(
        (sum: number, t: Record<string, any>) => sum + (t.order?.profit || 0),
        0
      );
      const winCount = log.filter(
        (t: Record<string, any>) => (t.order?.profit || 0) > 0
      ).length;
      const lossCount = log.filter(
        (t: Record<string, any>) => (t.order?.profit || 0) < 0
      ).length;
      const tradeCount = log.length;
      const pairs = Array.from(
        new Set(log.map((t: Record<string, any>) => t.pair))
      );
      const winRate = tradeCount > 0 ? winCount / tradeCount : 0;
      return res.json({
        confidence: last?.confidence ?? 0.5,
        usingRealFunds: last?.real_funds ?? false,
        log,
        analytics: {
          totalProfit,
          winRate,
          tradeCount,
          pairs,
          winCount,
          lossCount,
        },
      });
    }
    if (action === "auto") {
      // Automated trading/strategy management (background)
      // Get real-time confidence from QMOI AI
      const confidence = await calculateTradingConfidence();

      // Example: run every 30s, check confidence, place trade if high
      if (confidence > 0.7) {
        const pair = "BTCUSDT_UMCBL";
        const side = "open_long";
        const size = 0.01;
        try {
          const order = await bitgetRequest(
            "POST",
            "/api/v2/mix/order/placeOrder",
            {
              symbol: pair,
              marginCoin: "USDT",
              size,
              side,
              orderType: "market",
              productType: "USDT-FUTURES",
            }
          );
          tradeLog.push({
            time: Date.now(),
            pair,
            side,
            size,
            result: order,
            confidence,
            real_funds: true,
          });
          return res.json({ status: "trade-placed", order, confidence });
        } catch (e) {
          const errorMessage = e instanceof Error ? e.message : String(e);
          return res.json({ status: "error", error: errorMessage });
        }
      }
      return res.json({ status: "idle", confidence });
    }
    // Trading log route
    if (req.method === "GET") {
      // Return all trades
      if (fs.existsSync(TRADING_LOG)) {
        const trades = JSON.parse(fs.readFileSync(TRADING_LOG, "utf-8"));
        return res.status(200).json(trades);
      } else {
        return res.status(200).json([]);
      }
    } else if (req.method === "POST") {
      // Execute real trade based on QMOI AI analysis
      const confidence = await calculateTradingConfidence();

      if (confidence < 0.7) {
        return res.status(400).json({
          error: "Confidence too low for trade execution",
          confidence,
        });
      }

      // AI-determined trade parameters
      const pair = "BTCUSDT_UMCBL";
      const side = Math.random() > 0.5 ? "open_long" : "open_short";
      const size = 0.01;

      try {
        const order = await bitgetRequest(
          "POST",
          "/api/v2/mix/order/placeOrder",
          {
            symbol: pair,
            marginCoin: "USDT",
            size,
            side,
            orderType: "market",
            productType: "USDT-FUTURES",
          }
        );

        const trade = {
          id: order.orderId || Math.random().toString(36).slice(2),
          timestamp: Date.now(),
          type: side === "open_long" ? "BUY" : "SELL",
          amount: size,
          price: order.price || 0,
          result: "EXECUTED",
          rationale: `QMOI AI confidence: ${confidence.toFixed(2)}`,
          order,
          confidence,
          real_funds: true,
        };

        let trades = [];
        if (fs.existsSync(TRADING_LOG)) {
          trades = JSON.parse(fs.readFileSync(TRADING_LOG, "utf-8"));
        }
        trades.push(trade);
        fs.writeFileSync(TRADING_LOG, JSON.stringify(trades, null, 2));
        return res.status(201).json(trade);
      } catch (e) {
        const errorMessage = e instanceof Error ? e.message : String(e);
        return res
          .status(500)
          .json({ error: "Trade execution failed", details: errorMessage });
      }
    } else if (req.method === "DELETE") {
      // Clear all trades (master only)
      fs.writeFileSync(TRADING_LOG, "[]");
      return res.status(204).end();
    } else {
      return res.status(405).end();
    }
    return res.status(400).json({ error: "Unknown action" });
  } catch (e: any) {
    return res.status(500).json({ error: e.message });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { requireApiKey, writeProposal } from "../../../lib/proposals";
import { TradingService } from "../../../lib/services/trading";
import { connectToTradingEngine } from "../../../lib/services/trading-engine";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

interface Trade {
  id?: string;
  symbol: string;
  type: "buy" | "sell";
  amount: number;
  price: number;
  timestamp?: string;
  status?: "completed" | "pending" | "failed";
  profit?: number;
}

interface TradingStats {
  totalTrades: number;
  successfulTrades: number;
  failedTrades: number;
  totalProfit: number;
  winRate: number;
  averageProfit: number;
  bestTrade: Trade;
  worstTrade: Trade;
}

async function fetchTradingStats(): Promise<TradingStats> {
  const tradingService = TradingService.getInstance();
  return await tradingService.getTradingStats();
}

async function fetchTradeHistory(): Promise<Trade[]> {
  const tradingService = TradingService.getInstance();
  return await tradingService.getTradeHistory();
}

async function fetchActiveTrades(): Promise<Trade[]> {
  const tradingService = TradingService.getInstance();
  return await tradingService.getActiveTrades();
}

async function executeTrade(trade: Trade): Promise<Trade> {
  const tradingService = TradingService.getInstance();

  // Create initial trade record
  const newTrade = await tradingService.createTrade({
    ...trade,
    timestamp: new Date().toISOString(),
    status: "pending",
  });

  try {
    // Connect to your real trading engine here
    // This is where you'd integrate with your actual trading platform API
    const engine = await connectToTradingEngine();

    // Execute trade with engine
    const engineResult = await tradingService.executeTrade(trade);

    // Update trade with results
    const updated = await tradingService.updateTrade(newTrade.id || "", {
      status: "completed",
      profit: engineResult.profit || 0,
    });
    return updated || newTrade;
  } catch (error) {
    // If trade fails, update status
    await tradingService.updateTrade(newTrade.id || "", {
      status: "failed",
      profit: 0,
    });
    throw error;
  }
}

async function cancelTrade(
  tradeId: string,
): Promise<{ success: boolean; message: string }> {
  const tradingService = TradingService.getInstance();

  try {
    // First check if trade exists and is pending
    const cancelled = await tradingService.cancelTrade(tradeId);

    if (!cancelled) {
      return {
        success: false,
        message: "Trade not found or already completed/cancelled",
      };
    }

    // Here you would also cancel the trade on your trading platform if needed
    // For now we just handle the database state

    return {
      success: true,
      message: "Trade cancelled successfully",
    };
  } catch (error) {
    console.error("Error cancelling trade:", error);
    return {
      success: false,
      message:
        error instanceof Error
          ? error.message
          : "Unknown error cancelling trade",
    };
  }
}

export async function GET(request: NextRequest) {
  // Gate reads with API key as well
  const auth = await requireApiKey(request.headers);
  if (!auth.ok) return auth.response;

  try {
    const searchParams = request.nextUrl.searchParams;
    const stats = searchParams.get("stats");
    const history = searchParams.get("history");
    const active = searchParams.get("active");

    if (stats) {
      const statsData: TradingStats = await fetchTradingStats();
      return NextResponse.json(statsData);
    }

    if (history) {
      const tradeHistory: Trade[] = await fetchTradeHistory();
      return NextResponse.json({ trades: tradeHistory });
    }

    if (active) {
      const activeTrades: Trade[] = await fetchActiveTrades();
      return NextResponse.json({ activeTrades });
    }

    return NextResponse.json(
      { error: "Invalid query parameter" },
      { status: 400 },
    );
  } catch (error) {
    console.error("Error in QI trading endpoint:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Unknown error" },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest) {
  // Mutating actions are proposal-first by default
  const auth = await requireApiKey(request.headers);
  if (!auth.ok) return auth.response;

  try {
    const body = await request.json();
    const { action, trade } = body;

    const canRun = process.env.PRODUCTION_CONFIRMED === "true";

    if (action === "execute") {
      if (!canRun) {
        await writeProposal({
          id: `trade-execute-${Date.now()}`,
          timestamp: new Date().toISOString(),
          action: "qi_trading_execute",
          details: { trade },
        });
        return NextResponse.json({
          status: "proposed",
          message:
            "Execute trade proposed. Set PRODUCTION_CONFIRMED=true to execute.",
        });
      }

      const executedTrade: Trade = await executeTrade(trade);
      return NextResponse.json({
        status: "success",
        message: "Trade executed successfully",
        trade: executedTrade,
      });
    }

    if (action === "cancel") {
      if (!canRun) {
        await writeProposal({
          id: `trade-cancel-${Date.now()}`,
          timestamp: new Date().toISOString(),
          action: "qi_trading_cancel",
          details: { tradeId: trade?.id },
        });
        return NextResponse.json({
          status: "proposed",
          message:
            "Cancel trade proposed. Set PRODUCTION_CONFIRMED=true to execute.",
        });
      }

      const cancelResult = await cancelTrade(trade.id);
      return NextResponse.json({
        status: cancelResult.success ? "success" : "error",
        message: cancelResult.message,
        tradeId: trade.id,
      });
    }

    return NextResponse.json(
      { error: "Invalid action specified" },
      { status: 400 },
    );
  } catch (error) {
    console.error("Error in QI trading execution endpoint:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Unknown error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";

// Dynamic import for Prisma to avoid build-time issues
let prisma: any = null;

async function getPrisma() {
  if (!prisma) {
    const imported = await import("@/lib/prisma");
    // support different export shapes
    prisma = imported.prisma || imported.default || imported;
  }
  return prisma;
}

// Media management types
interface MediaItem {
  id: string;
  title: string;
  type: "movie" | "series" | "documentary" | "animation";
  source: "public_domain" | "youtube" | "user_upload";
  url: string;
  localPath?: string;
  duration?: number;
  size?: number;
  status: "available" | "downloading" | "downloaded" | "error";
  createdAt: Date;
  updatedAt: Date;
}

// Master-only access check
function isMaster(request: NextRequest) {
  // TODO: Implement real master auth logic
  return request.headers.get("x-qmoi-master") === "true";
}

// Media search implementation
async function searchMedia(
  query: string,
  type?: string,
  source?: string
): Promise<MediaItem[]> {
  const prisma = await getPrisma();
  const where: any = {
    title: {
      contains: query,
      mode: "insensitive",
    },
  };

  if (type) {
    where.type = type;
  }

  if (source) {
    where.source = source;
  }

  const mediaTasks = await prisma.mediaTask.findMany({
    where,
    orderBy: {
      createdAt: "desc",
    },
  });

  // Convert to MediaItem format for compatibility
  return mediaTasks.map((task: any) => ({
    id: task.id,
    title: task.metadata?.title || task.type || "",
    type: (task.metadata?.type as any) || ("movie" as const),
    source: (task.metadata?.source as any) || ("public_domain" as const),
    url: task.result || task.metadata?.url || "",
    status:
      task.status === "completed"
        ? "downloaded"
        : task.status === "processing"
        ? "downloading"
        : "available",
    createdAt: task.createdAt,
    updatedAt: task.updatedAt,
  }));
}

// Download media implementation
async function downloadMedia(mediaId: string) {
  const prisma = await getPrisma();
  const mediaTask = await prisma.mediaTask.findUnique({
    where: { id: mediaId },
  });

  if (!mediaTask) {
    return { success: false, message: "Media not found" };
  }

  if (mediaTask.status === "completed") {
    return { success: true, message: "Media already downloaded" };
  }

  try {
    // Update status to processing
    await prisma.mediaTask.update({
      where: { id: mediaId },
      data: { status: "processing" },
    });

    // TODO: Implement actual download logic here
    // For now, just mark as completed
    await prisma.mediaTask.update({
      where: { id: mediaId },
      data: {
        status: "completed",
        result: "Downloaded successfully",
      },
    });

    return {
      success: true,
      message: "Media downloaded successfully",
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);

    await prisma.mediaTask.update({
      where: { id: mediaId },
      data: {
        status: "failed",
        error: errorMessage,
      },
    });

    return {
      success: false,
      message: `Download failed: ${errorMessage}`,
      error: errorMessage,
    };
  }
}

// Get media logs (using audit logs for now)
async function getMediaLogs(filter?: {
  action?: string;
  mediaId?: string;
  limit?: number;
}) {
  const prisma = await getPrisma();
  const where: any = {};

  if (filter?.action) {
    where.action = filter.action;
  }

  if (filter?.mediaId) {
    where.resource = filter.mediaId;
  }

  const logs = await prisma.auditLog.findMany({
    where,
    orderBy: {
      timestamp: "desc",
    },
    take: filter?.limit || 50,
  });

  return logs;
}

export async function GET(request: NextRequest) {
  if (!isMaster(request)) {
    return NextResponse.json(
      { error: "Master access required" },
      { status: 403 }
    );
  }

  const { searchParams } = new URL(request.url);

  // Media search endpoint
  const searchQuery = searchParams.get("search");
  if (searchQuery) {
    try {
      const results = await searchMedia(
        searchQuery,
        searchParams.get("type") || undefined,
        searchParams.get("source") || undefined
      );
      return NextResponse.json({ media: results });
    } catch (error) {
      return NextResponse.json(
        { error: `Search failed: ${error}` },
        { status: 500 }
      );
    }
  }

  // Get media logs endpoint
  if (searchParams.get("logs")) {
    try {
      const logs = await getMediaLogs({
        action: searchParams.get("action") || undefined,
        mediaId: searchParams.get("mediaId") || undefined,
        limit: searchParams.get("limit")
          ? parseInt(searchParams.get("limit")!)
          : undefined,
      });
      return NextResponse.json({ logs });
    } catch (error) {
      return NextResponse.json(
        { error: `Failed to get logs: ${error}` },
        { status: 500 }
      );
    }
  }

  // Get database info
  if (searchParams.get("info")) {
    try {
      const prisma = await getPrisma();
      const userCount = await prisma.user.count();
      const auditLogCount = await prisma.auditLog.count();
      const mediaTaskCount = await prisma.mediaTask.count();

      return NextResponse.json({
        users: userCount,
        auditLogs: auditLogCount,
        mediaTasks: mediaTaskCount,
      });
    } catch (error) {
      return NextResponse.json(
        { error: `Failed to get database info: ${error}` },
        { status: 500 }
      );
    }
  }

  return NextResponse.json({ error: "Invalid request" }, { status: 400 });
}

export async function POST(request: NextRequest) {
  if (!isMaster(request)) {
    return NextResponse.json(
      { error: "Master access required" },
      { status: 403 }
    );
  }

  try {
    const body = await request.json();
    const prisma = await getPrisma();

    // Media download endpoint
    if (body.download) {
      const result = await downloadMedia(body.mediaId);
      return NextResponse.json(result);
    }

    // Add new media task
    if (body.addMedia) {
      const mediaTask = await prisma.mediaTask.create({
        data: {
          type: body.type || "video",
          status: "pending",
          metadata: JSON.stringify({
            title: body.title,
            source: body.source,
            url: body.url,
          }),
        },
      });

      return NextResponse.json({
        success: true,
        media: {
          id: mediaTask.id,
          title: body.title,
          type: body.type,
          source: body.source,
          url: body.url,
          status: mediaTask.status,
          createdAt: mediaTask.createdAt,
          updatedAt: mediaTask.updatedAt,
        },
      });
    }

    // Create audit log
    if (body.logAction) {
      const auditLog = await prisma.auditLog.create({
        data: {
          userId: body.userId || "system",
          username: body.username || "system",
          action: body.action,
          resource: body.resource || "media",
          details: JSON.stringify(body.details || {}),
          riskLevel: body.riskLevel || "low",
          status: "success",
          sessionId: body.sessionId,
        },
      });

      return NextResponse.json({ success: true, log: auditLog });
    }

    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  } catch (error) {
    return NextResponse.json(
      { error: `Request failed: ${error}` },
      { status: 500 }
    );
  }
}

